"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["44577"],{1919(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>c,frontMatter:()=>o,contentTitle:()=>r,toc:()=>l,assets:()=>h});var s=JSON.parse('{"id":"tangfen/anothersuggestion","title":"","description":"It seems I\'m rather suited to being a lawyer, since I\'m now defending the arguments of Marx and Miss Chan. But at the same time I\'ve discovered a problem","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/anothersuggestion.md","sourceDirName":"tangfen","slug":"/tangfen/anothersuggestion","permalink":"/en/tangfen/anothersuggestion","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"anothersuggestion","title":"","hide_table_of_contents":true,"sidebar_label":"Another suggestion: if refuting Marx or Ms. Chan, first understand their ideas clearly \u2014 don\'t fabricate on your own!"},"sidebar":"tangfenSidebar","previous":{"title":"Chuanliu, let me tell you what things are like \\"Chuanliu\'s will\\"! But labor is not!","permalink":"/en/tangfen/chliuwill"},"next":{"title":"[French Chef], please distinguish the essential difference between human thought and computers!","permalink":"/en/tangfen/toflxdcsf4"}}'),a=n(74848),i=n(28453);let o={id:"anothersuggestion",title:"",hide_table_of_contents:!0,sidebar_label:"Another suggestion: if refuting Marx or Ms. Chan, first understand their ideas clearly \u2014 don't fabricate on your own!"},r="Another Suggestion: If You Want to Refute Marx or Miss Chan, First Get Their Ideas Straight -- Don't Fabricate!",h={},l=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"another-suggestion-if-you-want-to-refute-marx-or-miss-chan-first-get-their-ideas-straight----dont-fabricate",children:"Another Suggestion: If You Want to Refute Marx or Miss Chan, First Get Their Ideas Straight -- Don't Fabricate!"})}),"\n",(0,a.jsx)(t.p,{children:"It seems I'm rather suited to being a lawyer, since I'm now defending the arguments of Marx and Miss Chan. But at the same time I've discovered a problem: the attackers haven't even understood the ideas of their targets before they set up a signboard, flail at it wildly, then declare victory. Is the forum really so fond of playing Ah Q these days? Roughly grouped by faction, those who attack Marx are all rightists; those who attack Miss Chan are all leftists. So this problem transcends factions and is a universal phenomenon. Just take today's posts as an example:"}),"\n",(0,a.jsx)(t.p,{children:'For instance:\n"\n[Falanxi Dacai Shifu] posted on 2006-08-11 14:13:37'}),"\n",(0,a.jsxs)(t.p,{children:["--------------------------------------------------------------------------------",(0,a.jsx)("br",{})]}),"\n",(0,a.jsxs)(t.p,{children:["Congratulations again, Tangfen, for knowing to approach from physics.",(0,a.jsx)("br",{}),"\nI said before:",(0,a.jsx)("br",{}),"\nMathematical arguments are not impervious. They can be refuted from physics. But the Chan girl choosing to refute from mathematics was a grave error."]}),"\n",(0,a.jsx)(t.p,{children:"Those who oppose Miss Chan's proof all make the same mistake: they don't realize that the examination of human thought must be conducted simultaneously in mathematical and physical space. Humans are real humans, not abstract symbolic tokens. So using examples of all finite natural numbers to refute Miss Chan is obviously barking up the wrong tree, and also reflects the metaphysical aspect of the opponents' thinking.\""}),"\n",(0,a.jsx)(t.p,{children:"But everyone, look at Miss Chan's proof: \"Because the leftist hypothesis states that 'all linguistically expressible human thoughts can be stored in a binary computer,' these thoughts constitute a set A, where thoughts are denoted by an, with n representing natural numbers. Since the universe will perish, and the time interval for humans to produce a thought cannot be infinitely short (otherwise it would violate the principles of quantum mechanics), we can know that the elements in set A are finite, though the quantity can be very large. Then we construct a thought as follows: U (the expression of this thought differs from thought an), where U represents logical conjunction, and an represents all elements of set A. This thought is obviously not in set A, and it cannot be simplified into any thought in A, because this thought speaks of expression, so any tricks of logical simplification are useless. Since set A is finite, the expression of this thought is also finite, and this thought is obviously a human thought. The contradiction can only come from the leftist hypothesis that 'all linguistically expressible human thoughts can be stored in a binary computer' -- meaning this hypothesis is absurd.\""}),"\n",(0,a.jsx)(t.p,{children:"Doesn't Miss Chan's mention of \"otherwise it would violate the principles of quantum mechanics\" constitute examination from the physics side? How did it become purely mathematical? Miss Chan's proof has been up for many days now, and today there are still people like this. Isn't this problem a bit too serious?"}),"\n",(0,a.jsx)(t.p,{children:"More important than Miss Chan's problem is the issue of Marx's labor theory of value. Marx never, at any point, treated any single factor or a priori premise as the sole determinant of value. Anyone who has truly understood Marx knows this. Yet for over a century, those who supposedly refute Marx or defend Marx often commit this very error, sometimes even deliberately. Is this really a scientific attitude? Today, I just wrote that \"labor time determines value\" is NOT Marx's view -- it is precisely the view Marx criticized. This can be verified by consulting Marx's critique of Proudhon. But immediately two people continued to pin this slander on Marx. See:"}),"\n",(0,a.jsxs)(t.p,{children:['"',(0,a.jsx)("br",{}),"\n[Chuanliu] posted on 2006-08-11 14:26:44"]}),"\n",(0,a.jsxs)(t.p,{children:["--------------------------------------------------------------------------------",(0,a.jsx)("br",{})]}),"\n",(0,a.jsx)(t.p,{children:"If you replace 'labor time' with 'Tangfen's will'"}),"\n",(0,a.jsx)(t.p,{children:"If the proposition that labor value determines price holds, then the proposition that Tangfen's will determines price also holds. As long as you replace labor time with Tangfen's will, you can clearly see that the correctness and absurdity of these two propositions are almost identical.\""}),"\n",(0,a.jsx)(t.p,{children:'"[Yunguzi] posted on 2006-08-11 14:22:13'}),"\n",(0,a.jsxs)(t.p,{children:["--------------------------------------------------------------------------------",(0,a.jsx)("br",{}),'\nIn summary, nothing can exist in isolation, and nothing can be determined by a single factor. Therefore, abstract labor, expenditure of living labor, mere congealment of undifferentiated human labor -- such single factors cannot determine the value of commodities. The labor theory of value is an incorrect theory."']}),"\n",(0,a.jsx)(t.p,{children:"All of the above are typical examples of people who haven't figured out what Marx actually said, yet shout that Marx has been defeated. The most important thing in scientific research is objectivity, and it's the same in debate -- first get the other person's views straight. Is that really such a high demand? If the forum's level is to rise further, this bad phenomenon must change, otherwise it will be very difficult!"})]})}function c(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var s=n(96540);let a={},i=s.createContext(a);function o(e){let t=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);